<?php declare(strict_types=1); $base=config('app.base_path'); $isTrash=!empty($trash); ?>
<div class="page-header"><div><h1><?= $isTrash ? 'Deleted Restaurants' : 'Restaurants' ?></h1><p><?= $isTrash ? 'Restore restaurant businesses that were moved to Trash.' : 'Restaurant businesses registered under this tenant.' ?></p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/restaurants">Active Restaurants</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/restaurants?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/restaurant/restaurants/create">Add Restaurant</a><?php endif; ?></div></div>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Restaurant</th><th>City</th><th>District</th><th>Items</th><th>Status</th><th><?= $isTrash?'Deleted At':'Actions' ?></th></tr></thead><tbody><?php if(empty($restaurants)): ?><tr><td colspan="6"><div class="empty-state"><?= $isTrash?'Trash is empty.':'No restaurant profiles found.' ?></div></td></tr><?php else: foreach($restaurants as $r): ?><tr><td><strong><?= htmlspecialchars((string)$r['business_name'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars((string)($r['city']??'—'),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)($r['district']??'—'),ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$r['item_count'] ?> items</td><td><?= htmlspecialchars((string)$r['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($isTrash): ?><small><?= htmlspecialchars((string)($r['deleted_at']??'—'),ENT_QUOTES,'UTF-8') ?></small><form method="post" action="<?= $base ?>/restaurant/restaurants/<?= (int)$r['id'] ?>/restore" style="display:inline;margin-left:10px"><button class="btn btn-secondary" type="submit">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/restaurant/restaurants/<?= (int)$r['id'] ?>">View</a> <a class="link-button" href="<?= $base ?>/restaurant/restaurants/<?= (int)$r['id'] ?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
